    <div class="adventure-hud" id="adventure-hud" hidden><span class="adventure-coins" id="adventure-coins" aria-label="もらったコイン"><i class="coin-icon"></i><b id="coin-count">0</b></span><span class="adventure-place" id="adventure-place"></span></div>
